+    function barChart(svgEl, items, opts) {
+      // items: [{label, value, color?}]
+      const W = opts.width ?? 980;
+      const H = opts.height ?? 280;
+      const pad = {l:180, r:16, t:18, b:20};
+      const maxV = Math.max(...items.map(d=>d.value));
+
+      svgEl.setAttribute('viewBox', `0 0 ${W} ${H}`);
+      svgEl.innerHTML = '';
+
+      const rowH = (H - pad.t - pad.b) / items.length;
+      const barMaxW = W - pad.l - pad.r;
+
+      // grid lines
+      const gGrid = document.createElementNS('http://www.w3.org/2000/svg','g');
+      const ticks = 4;
+      for (let i=0;i<=ticks;i++){
+        const x = pad.l + (i/ticks)*barMaxW;
+        const ln = document.createElementNS('http://www.w3.org/2000/svg','line');
+        ln.setAttribute('x1', x);
+        ln.setAttribute('x2', x);
+        ln.setAttribute('y1', pad.t);
+        ln.setAttribute('y2', H-pad.b);
+        ln.setAttribute('stroke','rgba(255,255,255,.08)');
+        ln.setAttribute('stroke-width','1');
+        gGrid.appendChild(ln);
+      }
+      svgEl.appendChild(gGrid);
+
+      const g = document.createElementNS('http://www.w3.org/2000/svg','g');
+      items.forEach((d,i)=>{
+        const y = pad.t + i*rowH;
+
+        const label = document.createElementNS('http://www.w3.org/2000/svg','text');
+        label.setAttribute('x', pad.l-12);
+        label.setAttribute('y', y + rowH*0.62);
+        label.setAttribute('text-anchor','end');
+        label.setAttribute('fill','rgba(232,238,252,.85)');
+        label.setAttribute('font-size','12');
+        label.textContent = d.label;
+        g.appendChild(label);
+
+        const w = maxV === 0 ? 0 : (d.value/maxV)*barMaxW;
+        const rect = document.createElementNS('http://www.w3.org/2000/svg','rect');
+        rect.setAttribute('x', pad.l);
+        rect.setAttribute('y', y + rowH*0.22);
+        rect.setAttribute('width', Math.max(0, w));
+        rect.setAttribute('height', rowH*0.56);
+        rect.setAttribute('rx', 6);
+        rect.setAttribute('fill', d.color || 'rgba(77,163,255,.85)');
+        g.appendChild(rect);
+
+        const val = document.createElementNS('http://www.w3.org/2000/svg','text');
+        val.setAttribute('x', pad.l + w + 8);
+        val.setAttribute('y', y + rowH*0.62);
+        val.setAttribute('fill','rgba(232,238,252,.75)');
+        val.setAttribute('font-size','11');
+        val.textContent = opts.valueFormatter ? opts.valueFormatter(d.value) : String(d.value);
+        g.appendChild(val);
+      });
+      svgEl.appendChild(g);
+    }
